"""Genera las páginas estáticas desde contenido revisado, con navegación y metadatos comunes."""
from pathlib import Path
from html import escape as e
import json
ROOT=Path(__file__).resolve().parents[1]
BASE='https://bastiiiuuu.github.io/'
PROJECTS=json.loads((ROOT/'content/projects.json').read_text(encoding='utf-8'))

def head(title,description,path='',prefix=''):
 url=BASE+path
 data={'@context':'https://schema.org','@type':'WebSite' if not path else 'CreativeWork','name':title,'description':description,'url':url,'inLanguage':'es-CL'}
 return f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · Portafolio de software</title><meta name="description" content="{e(description)}"><meta name="theme-color" content="#101315"><meta name="color-scheme" content="dark"><link rel="canonical" href="{url}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/social.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{prefix}assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}styles.css"><script src="{prefix}app.js" defer></script><script type="application/ld+json">{json.dumps(data,ensure_ascii=False)}</script></head>'''

def nav(prefix=''):
 home=prefix+'index.html' if prefix else ''
 return f'''<a class="skip" href="#contenido">Saltar al contenido</a><header class="site-header"><nav class="wrap nav" aria-label="Principal"><a class="brand" href="{home or '#inicio'}"><img src="{prefix}assets/mark.svg" width="32" height="32" alt=""><span>Software<span class="brand-sub"> / Portfolio</span></span></a><button class="menu-toggle" aria-controls="nav-links" aria-expanded="false">Menú</button><div id="nav-links" class="nav-links"><a href="{home}#proyectos">Proyectos</a><a href="{home}#perfil">Perfil</a><a href="{home}#tecnologias">Tecnologías</a><a href="{home}#trayectoria">Formación</a><a href="{home}#contacto">Contacto</a></div><a class="nav-cv" href="{prefix}curriculum.html">Currículum</a></nav></header>'''

def footer(prefix=''):
 return f'''<footer class="wrap footer"><a class="brand" href="{prefix}index.html">Software / Portfolio</a><p>Desarrollo, integración y aprendizaje continuo.</p><a href="https://github.com/bastiiiuuu">GitHub</a><span>2026 · Chile</span></footer>'''

def tags(project):return '<ul class="tags" aria-label="Tecnologías">'+''.join('<li>'+e(v)+'</li>' for v in project['tech'])+'</ul>'
def image(file,alt,cls='',eager=False,prefix=''):
 # Las dimensiones intrínsecas se conservan para reservar espacio antes de la carga.
 if file.endswith('.svg'):w,h=960,540
 else:
  w,h=json.loads((ROOT/'content/images.json').read_text(encoding='utf-8'))[file]
 variants=json.loads((ROOT/'content/images.json').read_text(encoding='utf-8'))
 responsive=''
 if file.endswith('.webp'):
  options=[f'{prefix}assets/{name} {variants[name][0]}w' for name in [file.replace('.webp','-480.webp'),file.replace('.webp','-800.webp'),file] if name in variants]
  responsive=' srcset="'+', '.join(options)+'" sizes="(max-width:800px) calc(100vw - 40px), '+('1000px' if prefix else '640px')+'"'
 return f'<img{responsive} class="{cls}" src="{prefix}assets/{file}" alt="{e(alt)}" width="{w}" height="{h}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'

def gallery(project):
 if not project['gallery']:return '<p class="evidence-note">La evidencia disponible en este caso es técnica. El esquema explica la arquitectura; no se presenta como captura de una interfaz o de un sistema terminado.</p>'
 return '<div class="gallery">'+''.join(f'''<figure><a class="gallery-image" href="../assets/{g['file']}" data-lightbox aria-label="Ampliar: {e(g['title'])}">{image(g['file'],g['title'],prefix='../')}</a><figcaption><strong>{e(g['title'])}</strong><span>{e(g['caption'])}</span></figcaption></figure>''' for g in project['gallery'])+'</div><p class="gallery-note">Selecciona una imagen para ampliarla. Presentación monocromática; los enlaces oficiales conservan el diseño original.</p>'

index=head('Desarrollo de software desde Chile','Proyectos de software web, escritorio y Android; desarrollo Lua e integración FiveM. Formación en INACAP y casos de estudio con evidencia real.')+'<body>'+nav()+'''<main id="contenido"><section class="intro wrap" id="inicio"><div class="intro-grid"><div class="intro-copy"><p class="eyebrow">DESARROLLO DE SOFTWARE / CHILE</p><h1>Software con<br><em>lógica y propósito.</em></h1><p class="intro-summary">Aplicaciones web, escritorio y Android.<br> Integración de sistemas y desarrollo con Lua.</p><div class="actions"><a class="button primary" href="#proyectos">Explorar proyectos</a><a class="text-link" href="curriculum.html">Ver currículum</a></div><div class="intro-foot"><span>Perfil junior</span><span>Formación en INACAP</span><span>Interés en trabajo remoto</span></div></div>'''
mis=next(p for p in PROJECTS if p['slug']=='misreinas')
index+='''<a class="intro-preview" href="proyectos/misreinas.html"><div class="preview-caption"><span>EN EL PORTAFOLIO</span><span>WEB / BACKEND</span></div>'''+image('misreinas-api.webp','Interfaz real del explorador de API de Mis Reinas',eager=True)+'''<div class="preview-footer"><strong>Mis Reinas</strong><span>Django · API JSON</span></div></a><div class="intro-context"><p class="eyebrow">LA BASE</p><p>Ingeniería en Ciberseguridad en curso.<br>Último año de la salida intermedia de Analista Programador.</p></div><div class="intro-stack"><p class="eyebrow">HERRAMIENTAS EN PRÁCTICA</p><p>Python <span>/</span> JavaScript <span>/</span> Kotlin <span>/</span> Lua</p><a class="text-link" href="#tecnologias">Ver cómo las utilizo</a></div></div></section>
<section class="section wrap projects" id="proyectos"><div class="section-heading"><div><p class="eyebrow">TRABAJO SELECCIONADO</p><h2>El proyecto.<br>Las decisiones detrás.</h2></div><p>Casos de estudio para recorrer el problema,<br>la implementación y la evidencia disponible.</p></div>'''
for slug in ['sefel','misreinas','deskisiao']:
 p=next(p for p in PROJECTS if p['slug']==slug)
 index+=f'''<article class="project-feature" data-repo="{ {'misreinas':'Misreinas','deskisiao':'','sefel':''}[slug] }"><a class="feature-image {slug}" href="proyectos/{slug}.html">{image(p['cover'],p['summary'])}<span class="image-note">{'INTERFAZ REAL · DATOS FICTICIOS' if slug=='sefel' else 'CAPTURA REAL DEL PROYECTO'}</span></a><div class="feature-copy"><span class="eyebrow">{e(p['category'])}</span><h3>{e(p['title'])}</h3><p>{e(p['summary'])}</p>{tags(p)}<p class="project-detail">{ {'sefel':'Dominio de negocio, precisión monetaria y conservación de documentos emitidos.','misreinas':'Relaciones de datos, filtros combinables y un contrato público de solo lectura.','deskisiao':'Navegación adaptable, identidad y búsqueda sobre una normativa estructurada.'}[slug]}</p><a class="text-link" href="proyectos/{slug}.html">Leer el caso de estudio</a><span class="repo-update"></span></div></article>'''
index+='''<div class="project-index-heading"><h3>Más áreas de desarrollo</h3><p>Proyectos independientes, con su propio alcance.</p></div><div class="project-index">'''
for p in PROJECTS:
 if p['slug'] in ['sefel','misreinas','deskisiao']:continue
 index+=f'''<a class="project-row" href="proyectos/{p['slug']}.html"><span class="row-category">{e(p['category'])}</span><div><h3>{e(p['title'])}</h3><p>{e(p['summary'])}</p></div><span class="row-status">{e(p['status'])}</span></a>'''
index+='''</div><div class="exercise-links"><span>Ejercicios adicionales</span><a href="https://bastiiiuuu.github.io/calculadora-notas-10-pts/">Calculadora de notas</a><a href="https://bastiiiuuu.github.io/cine-entradas-certamen-3/">Cálculo de entradas de cine</a></div><div class="github-sync"><p id="sync-status" role="status">Código, documentación y demos en los enlaces de cada proyecto.</p><button id="sync-github" type="button">Consultar actividad pública</button></div></section>
<section class="section profile-section" id="perfil"><div class="wrap profile-grid"><div><p class="eyebrow">SOBRE MÍ / PERFIL</p><h2>Construir.<br> Entender.<br> <span>Seguir aprendiendo.</span></h2></div><div class="profile-copy"><p class="large-copy">Mi formación conecta programación y ciberseguridad. Me interesa desarrollar aplicaciones y comprender cómo se relacionan la interfaz, las reglas y los datos.</p><p>Mis proyectos reúnen ejercicios académicos, prototipos y un entorno personal de FiveM. En ellos trabajo con formularios, persistencia, APIs, reglas de cálculo, eventos y recursos conectados.</p><p>Busco mi primera oportunidad como Analista Programador o desarrollador junior, con interés en trabajo remoto desde Chile. Presento el alcance de cada entrega y el apoyo de IA cuando corresponde, para que el código y las decisiones puedan revisarse con contexto.</p><a class="text-link" href="curriculum.html">Consultar perfil y currículum</a></div></div><div class="wrap capability-list"><div><h3>Desarrollo de software</h3><p>Lógica de negocio, validación, cálculos y persistencia en proyectos de escritorio y móvil.</p></div><div><h3>Desarrollo web</h3><p>Interfaces React, sitios estáticos y aplicaciones Django con endpoints de consulta.</p></div><div><h3>Integración e infraestructura</h3><p>Recursos FiveM, scripts Lua, dependencias, respaldos y despliegues acotados documentados.</p></div></div></section>
<section class="section wrap" id="tecnologias"><div class="section-heading"><div><p class="eyebrow">TECNOLOGÍAS Y HERRAMIENTAS</p><h2>La herramienta cambia.<br>El criterio se construye.</h2></div><p>Uso demostrado en los proyectos.<br>Sin porcentajes ni niveles arbitrarios.</p></div><dl class="technology-table"><div><dt>Interfaces web</dt><dd><strong>JavaScript · React · HTML · CSS</strong><p>Componentes, estado y persistencia local en React; navegación y búsqueda en sitios estáticos.</p></dd></div><div><dt>Backend y datos</dt><dd><strong>Python · Django · SQLite</strong><p>Modelos relacionados, consultas, formularios, API de lectura y pruebas de comportamiento.</p></dd></div><div><dt>Escritorio</dt><dd><strong>CustomTkinter · ReportLab · Decimal</strong><p>Interfaz de SEFEL, documentos y cálculos monetarios en su dominio de negocio.</p></dd></div><div><dt>Aplicaciones móviles</dt><dd><strong>Kotlin · Android · XML</strong><p>Navegación entre actividades, formularios, recursos y reglas de cálculo en un certamen.</p></dd></div><div><dt>Servidor FiveM</dt><dd><strong>Lua · QBCore · Ox · NUI · oxmysql</strong><p>Eventos, callbacks, validaciones del servidor y compatibilidad entre recursos de terceros.</p></dd></div><div><dt>Calidad y entrega</dt><dd><strong>Git · GitHub Actions · unittest · node:test</strong><p>Control de versiones, pruebas de regresión, verificaciones y publicación de demos.</p></dd></div></dl><p class="evidence-note">Three.js y FastAPI aparecen en el atlas realizado con apoyo de IA. Flutter, Node.js y PostgreSQL forman parte del stack propuesto de SmartAttendance 360; su integración sigue en desarrollo.</p></section>
<section class="section trajectory-section" id="trayectoria"><div class="wrap trajectory-grid"><div><p class="eyebrow">FORMACIÓN Y TRAYECTORIA</p><h2>Una base técnica<br>en evolución.</h2><p>La trayectoria se presenta desde la formación y los proyectos disponibles, sin atribuir experiencia laboral.</p></div><div class="timeline"><article><span>EN CURSO / INACAP</span><h3>Ingeniería en Ciberseguridad</h3><p>Último año correspondiente a la salida intermedia de Analista Programador. La fecha de titulación aún no está confirmada.</p></article><article><span>PROYECTOS ACADÉMICOS</span><h3>Aplicaciones y reglas de negocio</h3><p>SEFEL, Mis Reinas, el certamen Android y ejercicios React como espacios para conectar requisitos, interfaces y datos.</p></article><article><span>PROYECTO PERSONAL</span><h3>Desarrollo e integración FiveM</h3><p>Trabajo con Lua y mantenimiento del servidor Deskisiao; una web pública separada presenta la comunidad.</p></article><article><span>EN DESARROLLO / EQUIPO</span><h3>SmartAttendance 360</h3><p>Participación compartida en un sistema que propone conectar hardware, backend, web y móvil.</p></article></div></div></section>
<section class="section wrap" id="metodologia"><div class="section-heading"><div><p class="eyebrow">METODOLOGÍA DE TRABAJO</p><h2>Entender antes de ampliar.</h2></div><p>Prácticas reflejadas en las mejoras<br>documentadas de los proyectos.</p></div><div class="method-grid"><article><h3>Definir el alcance</h3><p>Identificar el problema y distinguir requisitos implementados, demostraciones y funciones pendientes.</p></article><article><h3>Separar responsabilidades</h3><p>Organizar interfaz, reglas y datos para revisar cada parte sin mezclar sus contratos.</p></article><article><h3>Comprobar los límites</h3><p>Probar validaciones, datos inválidos, errores de almacenamiento y respuestas del sistema.</p></article><article><h3>Documentar la entrega</h3><p>Conservar instalación, pruebas, decisiones y pendientes para reproducir y explicar el resultado.</p></article></div></section>
<section class="section contact-section" id="contacto"><div class="wrap contact-grid"><div><p class="eyebrow">PRÓXIMO PASO</p><h2>Primera oportunidad.<br><span>Un nuevo equipo.</span></h2><p>Interés en desarrollo de software junior y trabajo remoto desde Chile. El currículum reúne mi formación y los proyectos que puedes explorar aquí.</p></div><div class="contact-links"><a href="curriculum.html"><span>Perfil profesional</span><strong>Consultar currículum</strong></a><a href="https://github.com/bastiiiuuu"><span>Código y repositorios</span><strong>GitHub</strong></a><p>Correo profesional y LinkedIn pendientes de definir. Por ahora se publican el perfil y el código disponibles.</p></div></div></section></main>'''+footer()+'</body></html>'
(ROOT/'index.html').write_text(index,encoding='utf-8')
for i,p in enumerate(PROJECTS):
 prefix='../';path='proyectos/'+p['slug']+'.html'
 s=head(p['title'],p['summary'],path,prefix)+'<body>'+nav(prefix)+f'''<main id="contenido"><header class="case-hero wrap"><a class="breadcrumb" href="../index.html#proyectos">Todos los proyectos</a><p class="eyebrow">{e(p['category'])}</p><h1>{e(p['title'])}</h1><p class="case-lead">{e(p['summary'])}</p><div class="case-meta"><div><span>Estado</span><strong>{e(p['status'])}</strong></div><div><span>Contexto</span><strong>{'Participación compartida' if p['slug']=='smartattendance' else 'Académico' if p['slug'] in ['sefel','misreinas','agenda-android','tareas'] else 'Proyecto personal / aprendizaje'}</strong></div><div><span>Tecnologías</span><strong>{e(' · '.join(p['tech']))}</strong></div></div><div class="actions">'''
 if p['demo']:s+=f'<a class="button primary" href="{p["demo"]}">Explorar demo</a>'
 if p['code']:s+=f'<a class="button secondary" href="{p["code"]}">Código e instalación</a>'
 s+='</div></header><div class="wrap case-cover '+p['slug']+'">'+image(p['cover'],p['summary'],eager=True,prefix='../')+'</div><div class="wrap case-layout"><aside class="case-toc"><p class="eyebrow">EN ESTE CASO</p><nav aria-label="Contenido del caso">'
 for n,section in enumerate(p['sections']):s+=f'<a href="#seccion-{n}">{e(section["title"])}</a>'
 s+='<a href="#arquitectura">Arquitectura</a><a href="#evidencias">Evidencias visuales</a></nav></aside><article class="case-article">'
 for n,section in enumerate(p['sections']):s+=f'<section id="seccion-{n}"><h2>{e(section["title"])}</h2>{section["html"]}</section>'
 if p['slug']=='misreinas':s+='<section><h2>Verificación del catálogo</h2><p>La entrega documentada incluye diez pruebas de páginas, filtros, paginación, errores, escape, CSRF y solo lectura. El catálogo incorpora consultas relacionadas para limitar accesos repetidos a la base. El formulario de contacto valida datos, pero no envía mensajes; la API externa específica de la evaluación continúa pendiente de definición.</p></section>'
 s+='<section id="arquitectura"><h2>Arquitectura'+(' prevista' if p['slug']=='smartattendance' else ' del proyecto')+'</h2><div class="architecture-flow" role="img" aria-label="'+e(' conecta con '.join(p['flow']))+'">'+''.join('<div>'+e(v)+'</div>' for v in p['flow'])+'</div><p class="gallery-note">Esquema de responsabilidades. '+('Diseño propuesto, pendiente de integración.' if p['slug']=='smartattendance' else 'La descripción técnica distingue los componentes y su función.')+'</p></section><section id="evidencias"><h2>Evidencias visuales</h2>'+gallery(p)+'</section>'
 nextp=PROJECTS[(i+1)%len(PROJECTS)]
 s+=f'''<div class="case-next"><span>SIGUIENTE CASO</span><a href="{nextp['slug']}.html">{e(nextp['title'])}</a></div></article></div></main><dialog class="lightbox" aria-label="Imagen ampliada"><button type="button" class="lightbox-close" autofocus>Cerrar imagen</button><img alt=""><p></p></dialog>'''+footer('../')+'</body></html>'
 (ROOT/path).write_text(s,encoding='utf-8')
urls=['','curriculum.html']+['proyectos/'+p['slug']+'.html' for p in PROJECTS]
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+u+'</loc></url>' for u in urls)+'</urlset>',encoding='utf-8')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'sitemap.xml\n',encoding='utf-8')
print(f'Generadas portada y {len(PROJECTS)} páginas de casos.')
